│   ├── criteria.mjs            # Append-only registry of evaluation criteria (v1 and v2)
│   ├── criteria-ids.json       # Canonical registry of all criteria IDs for append-only verification
│   └── gem-reviews.json        # Human-editable manual review records (responsiveness, audits)
