### 2. The Criteria Registry (`data/criteria.mjs`)

```javascript
/**
 * Append-only Criteria Registry for ExploreGit Gems.
 *
 * RULES:
 * 1. Criteria IDs are permanent and immutable. Never delete or rename an ID.
 * 2. To change a rule, add a new criterion that supersedes it and bump CRITERIA_VERSION.
 * 3. Update data/criteria-ids.json whenever a criterion is added.
 */

export const CRITERIA_VERSION = 2;

export const THRESHOLDS = {
  stars: {
    legend: { min: 10000, max: Infinity },
    gem: { min: 1000, max: 9999 },
    'under-the-radar': { min: 150, max: 999 },
  },
  minAgeDays: {
    legend: 3 * 365,       // 3 years
    gem: 2 * 365,          // 2 years
    'under-the-radar': 180, // 6 months
  },
  recentPushDays: {
    legend: 180,
    gem: 90,
    'under-the-radar': 60,
  },
  minRecentContributors: {
    legend: 5,
    gem: 2,
    'under-the-radar': 1,
  },
  reviewExpiryDays: {
    issueResponsiveness: 90,
    independentAudit: 365,
  },
  securityCategories: ['security-privacy', 'security'],
  securityTags: ['security', 'privacy', 'cryptography', 'authenticator', 'password-manager'],
};

// Recognized OSI-approved SPDX license identifiers
const OSI_APPROVED_LICENSES = new Set([
  'MIT', 'Apache-2.0', 'GPL-2.0', 'GPL-3.0', 'AGPL-3.0', 'LGPL-2.1', 'LGPL-3.0',
  'BSD-2-Clause', 'BSD-3-Clause', 'MPL-2.0', 'ISC', 'Unlicense', 'EUPL-1.2',
  '0BSD', 'CC0-1.0', 'Artistic-2.0'
]);

function getTier(entry) {
  if (entry.tier) return entry.tier;
  if (entry.isLegend) return 'legend';
  if (entry.isUnderTheRadar) return 'under-the-radar';
  return 'gem';
}

function isSecurityRelated(entry) {
  if (THRESHOLDS.securityCategories.includes(entry.category)) return true;
  if (Array.isArray(entry.topics)) {
    return entry.topics.some((t) => THRESHOLDS.securityTags.includes(t.toLowerCase()));
  }
  return false;
}

export const CRITERIA = [
  // ── Version 1: Core Quality & Activity Baseline ───────────────────────────
  {
    id: 'not-archived-or-disabled',
    since: 1,
    kind: 'auto',
    applies: () => true,
    check: (_entry, { repo }) => {
      if (repo.archived) return { pass: false, reason: 'Repository is archived' };
      if (repo.disabled) return { pass: false, reason: 'Repository is disabled' };
      return { pass: true };
    },
  },
  {
    id: 'not-a-fork',
    since: 1,
    kind: 'auto',
    applies: () => true,
    check: (_entry, { repo }) => {
      if (repo.fork) return { pass: false, reason: 'Repository is a fork, not upstream source' };
      return { pass: true };
    },
  },
  {
    id: 'osi-approved-license',
    since: 1,
    kind: 'auto',
    applies: () => true,
    check: (_entry, { repo }) => {
      const spdx = repo.license?.spdx_id;
      if (!spdx || spdx === 'NOASSERTION' || spdx === 'NONE') {
        return { pass: false, reason: `Unrecognized or missing license (${spdx || 'none'})` };
      }
      if (!OSI_APPROVED_LICENSES.has(spdx)) {
        return { pass: false, reason: `License (${spdx}) is not recognized as OSI-approved` };
      }
      return { pass: true };
    },
  },
  {
    id: 'has-description',
    since: 1,
    kind: 'auto',
    applies: () => true,
    check: (_entry, { repo }) => {
      if (!repo.description || repo.description.trim().length === 0) {
        return { pass: false, reason: 'Repository has no description on GitHub' };
      }
      return { pass: true };
    },
  },
  {
    id: 'stars-within-tier',
    since: 1,
    kind: 'auto',
    applies: () => true,
    check: (entry, { repo }) => {
      const tier = getTier(entry);
      const bounds = THRESHOLDS.stars[tier];
      const stars = repo.stargazers_count ?? 0;
      if (stars < bounds.min || stars > bounds.max) {
        return {
          pass: false,
          reason: `Stars (${stars}) outside window for tier "${tier}" (${bounds.min} - ${bounds.max})`,
        };
      }
      return { pass: true };
    },
  },
  {
    id: 'min-repo-age',
    since: 1,
    kind: 'auto',
    applies: () => true,
    check: (entry, { repo, now = new Date() }) => {
      const tier = getTier(entry);
      const minDays = THRESHOLDS.minAgeDays[tier];
      const createdAt = new Date(repo.created_at);
      const ageDays = (now.getTime() - createdAt.getTime()) / (1000 * 60 * 60 * 24);
      if (ageDays < minDays) {
        return {
          pass: false,
          reason: `Repository age (${Math.floor(ageDays)} days) is below required ${minDays} days for tier "${tier}"`,
        };
      }
      return { pass: true };
    },
  },
  {
    id: 'recent-push',
    since: 1,
    kind: 'auto',
    applies: () => true,
    check: (entry, { repo, now = new Date() }) => {
      const tier = getTier(entry);
      const maxDays = THRESHOLDS.recentPushDays[tier];
      const pushedAt = new Date(repo.pushed_at);
      const inactiveDays = (now.getTime() - pushedAt.getTime()) / (1000 * 60 * 60 * 24);
      if (inactiveDays > maxDays) {
        return {
          pass: false,
          reason: `Last push was ${Math.floor(inactiveDays)} days ago (limit: ${maxDays} days for "${tier}")`,
        };
      }
      return { pass: true };
    },
  },
  {
    id: 'min-recent-contributors',
    since: 1,
    kind: 'auto',
    applies: () => true,
    check: (entry, { commits = [] }) => {
      const tier = getTier(entry);
      const minRequired = THRESHOLDS.minRecentContributors[tier];
      const authors = new Set();
      for (const commit of commits) {
        const authorId = commit.author?.login || commit.commit?.author?.email;
        if (authorId) authors.add(authorId);
      }
      if (authors.size < minRequired) {
        return {
          pass: false,
          reason: `Found only ${authors.size} unique commit contributor(s) recently (requires $\ge ${minRequired}$)`,
        };
      }
      return { pass: true };
    },
  },
  {
    id: 'tagged-release-required',
    since: 1,
    kind: 'auto',
    applies: (entry) => {
      const tier = getTier(entry);
      return tier === 'legend' || tier === 'gem';
    },
    check: (_entry, { latestRelease }) => {
      if (!latestRelease || !latestRelease.tag_name) {
        return { pass: false, reason: 'No tagged releases found (required for Legend and Gem tiers)' };
      }
      return { pass: true };
    },
  },

  // ── Version 2: Security, Governance & Verification ────────────────────────
  {
    id: 'readme-present',
    since: 2,
    kind: 'auto',
    applies: () => true,
    check: (_entry, { communityProfile }) => {
      const hasReadme = Boolean(communityProfile?.files?.readme);
      if (!hasReadme) {
        return { pass: false, reason: 'Repository lacks a standard README documentation file' };
      }
      return { pass: true };
    },
  },
  {
    id: 'published-security-policy',
    since: 2,
    kind: 'auto',
    applies: (entry) => isSecurityRelated(entry),
    check: (_entry, { communityProfile }) => {
      const hasSecPolicy = Boolean(communityProfile?.files?.security_policy);
      if (!hasSecPolicy) {
        return { pass: false, reason: 'No published SECURITY.md policy found for security-sensitive tool' };
      }
      return { pass: true };
    },
  },
  {
    id: 'issue-responsiveness',
    since: 2,
    kind: 'manual',
    applies: () => true,
    check: (entry, { reviewRecord, now = new Date() }) => {
      const review = reviewRecord?.issueResponsiveness;
      if (!review || !review.verifiedAt) {
        return { pass: false, reason: 'Manual review required: issue responsiveness has not been verified' };
      }
      const verifiedAt = new Date(review.verifiedAt);
      const elapsedDays = (now.getTime() - verifiedAt.getTime()) / (1000 * 60 * 60 * 24);
      if (elapsedDays > THRESHOLDS.reviewExpiryDays.issueResponsiveness) {
        return {
          pass: false,
          reason: `Issue responsiveness review expired (${Math.floor(elapsedDays)} days old, max ${THRESHOLDS.reviewExpiryDays.issueResponsiveness})`,
        };
      }
      return { pass: true };
    },
  },
  {
    id: 'independent-audit',
    since: 2,
    kind: 'manual',
    applies: (entry) => isSecurityRelated(entry),
    check: (entry, { reviewRecord, now = new Date() }) => {
      const review = reviewRecord?.independentAudit;
      if (!review || !review.verifiedAt || !review.auditUrl) {
        return { pass: false, reason: 'Manual review required: independent audit has not been verified' };
      }
      const verifiedAt = new Date(review.verifiedAt);
      const elapsedDays = (now.getTime() - verifiedAt.getTime()) / (1000 * 60 * 60 * 24);
      if (elapsedDays > THRESHOLDS.reviewExpiryDays.independentAudit) {
        return {
          pass: false,
          reason: `Independent audit verification expired (${Math.floor(elapsedDays)} days old, max ${THRESHOLDS.reviewExpiryDays.independentAudit})`,
        };
      }
      return { pass: true };
    },
  },
];
