### 3. The Evaluator Script (`scripts/evaluate-gems.mjs`)

```javascript
#!/usr/bin/env node

/**
 * ExploreGit Monthly Gems Evaluator
 * Evaluates manifest entries against criteria.mjs with rate-limiting and retry backoff.
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { CRITERIA, CRITERIA_VERSION } from '../data/criteria.mjs';
import { GEMS_MANIFEST } from '../src/data/gemsManifest.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT_DIR = path.resolve(__dirname, '..');

const GITHUB_TOKEN = process.env.GITHUB_TOKEN || '';
const RATE_LIMIT_DELAY_MS = 600; // Throttle to ~100 requests/minute (safe for 5000/hr limit)

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function fetchWithRetry(url, options = {}, retries = 3) {
  const headers = {
    Accept: 'application/vnd.github.v3+json',
    'User-Agent': 'ExploreGit-Gems-Evaluator/2.0',
    ...(GITHUB_TOKEN ? { Authorization: `Bearer ${GITHUB_TOKEN}` } : {}),
    ...options.headers,
  };

  for (let attempt = 1; attempt <= retries; attempt++) {
    await sleep(RATE_LIMIT_DELAY_MS);
    try {
      const res = await fetch(url, { ...options, headers });

      if (res.status === 404) {
        return { ok: false, status: 404, data: null };
      }

      if (res.status === 403 || res.status === 429) {
        const retryAfter = res.headers.get('Retry-After');
        const resetTime = res.headers.get('x-ratelimit-reset');
        let waitMs = 5000 * Math.pow(2, attempt);

        if (retryAfter) {
          waitMs = parseInt(retryAfter, 10) * 1000;
        } else if (resetTime) {
          waitMs = Math.max(1000, parseInt(resetTime, 10) * 1000 - Date.now() + 1000);
        }

        console.warn(`[WARN] Rate limited on ${url}. Waiting ${Math.round(waitMs / 1000)}s...`);
        await sleep(waitMs);
        continue;
      }

      if (!res.ok) {
        throw new Error(`HTTP ${res.status}: ${res.statusText}`);
      }

      const data = await res.json();
      return { ok: true, status: res.status, data };
    } catch (err) {
      if (attempt === retries) throw err;
      await sleep(2000 * attempt);
    }
  }
}

async function loadPreviousState() {
  try {
    const raw = await fs.readFile(path.join(ROOT_DIR, 'public/data/gems.json'), 'utf-8');
    return JSON.parse(raw);
  } catch {
    return { evaluatedAt: null, items: [] };
  }
}

async function loadReviews() {
  try {
    const raw = await fs.readFile(path.join(ROOT_DIR, 'data/gem-reviews.json'), 'utf-8');
    const parsed = JSON.parse(raw);
    return parsed.reviews || {};
  } catch {
    return {};
  }
}

async function fetchRepoData(repoFullName) {
  const [owner, repo] = repoFullName.split('/');
  const base = `https://api.github.com/repos/${owner}/${repo}`;

  const repoRes = await fetchWithRetry(base);
  if (!repoRes.ok && repoRes.status === 404) {
    return { unavailable: true };
  }
  if (!repoRes.ok) {
    throw new Error(`Failed to fetch repo ${repoFullName}`);
  }

  const [releaseRes, communityRes, commitsRes] = await Promise.all([
    fetchWithRetry(`${base}/releases/latest`).catch(() => ({ ok: false, data: null })),
    fetchWithRetry(`${base}/community/profile`).catch(() => ({ ok: false, data: null })),
    fetchWithRetry(`${base}/commits?per_page=30`).catch(() => ({ ok: false, data: [] })),
  ]);

  return {
    unavailable: false,
    repo: repoRes.data,
    latestRelease: releaseRes?.data || null,
    communityProfile: communityRes?.data || null,
    commits: Array.isArray(commitsRes?.data) ? commitsRes.data : [],
  };
}

export async function evaluateGems() {
  console.log(`[EVALUATOR] Starting Gems evaluation (Criteria v${CRITERIA_VERSION})...`);
  const now = new Date();
  const previousState = await loadPreviousState();
  const previousMap = new Map((previousState.items || []).map((item) => [item.repo.toLowerCase(), item]));
  const reviews = await loadReviews();

  const evaluatedItems = [];
  const changes = [];

  for (const manifestItem of GEMS_MANIFEST) {
    const repoKey = manifestItem.repo.toLowerCase();
    const prev = previousMap.get(repoKey);
    console.log(`[EVALUATOR] Processing ${manifestItem.repo}...`);

    let repoData;
    let fetchFailed = false;
    let fetchErrorReason = '';

    try {
      repoData = await fetchRepoData(manifestItem.repo);
    } catch (err) {
      fetchFailed = true;
      fetchErrorReason = err.message;
    }

    if (fetchFailed) {
      if (prev) {
        console.warn(`[WARN] Fetch failed for ${manifestItem.repo}. Retaining previous state as stale.`);
        evaluatedItems.push({
          ...prev,
          stale: true,
          staleReason: `GitHub fetch failed: ${fetchErrorReason}`,
        });
      } else {
        evaluatedItems.push({
          ...manifestItem,
          status: 'unknown',
          stale: true,
          staleReason: `Initial fetch failed: ${fetchErrorReason}`,
          reasons: ['Initial GitHub fetch failed'],
        });
      }
      continue;
    }

    if (repoData.unavailable) {
      const item = {
        ...manifestItem,
        status: 'unavailable',
        reasons: ['Repository deleted, made private, or moved without redirect'],
      };
      evaluatedItems.push(item);
      if (prev?.status && prev.status !== 'unavailable') {
        changes.push({ repo: manifestItem.repo, from: prev.status, to: 'unavailable' });
      }
      continue;
    }

    // Evaluate criteria
    const context = {
      now,
      repo: repoData.repo,
      latestRelease: repoData.latestRelease,
      communityProfile: repoData.communityProfile,
      commits: repoData.commits,
      reviewRecord: reviews[manifestItem.repo] || null,
    };

    const failedAuto = [];
    const failedManual = [];

    for (const criterion of CRITERIA) {
      if (!criterion.applies(manifestItem, context)) continue;

      const result = criterion.check(manifestItem, context);
      if (!result.pass) {
        if (criterion.kind === 'auto') {
          failedAuto.push({ id: criterion.id, reason: result.reason });
        } else {
          failedManual.push({ id: criterion.id, reason: result.reason });
        }
      }
    }

    let status = 'eligible';
    const reasons = [];

    if (failedAuto.length > 0) {
      status = 'below-threshold';
      reasons.push(...failedAuto.map((f) => f.reason));
    } else if (failedManual.length > 0) {
      status = 'pending-review';
      reasons.push(...failedManual.map((f) => f.reason));
    }

    const currentItem = {
      ...manifestItem,
      name: manifestItem.name || repoData.repo.name,
      description: repoData.repo.description || manifestItem.tagline,
      stars: repoData.repo.stargazers_count,
      forks: repoData.repo.forks_count,
      language: repoData.repo.language || 'Multi',
      license: repoData.repo.license?.spdx_id || 'Open Source',
      topics: repoData.repo.topics || [],
      githubUrl: repoData.repo.html_url,
      avatarUrl: repoData.repo.owner?.avatar_url,
      status,
      reasons,
      stale: false,
      evaluatedAt: now.toISOString(),
    };

    evaluatedItems.push(currentItem);

    if (prev?.status && prev.status !== status) {
      changes.push({
        repo: manifestItem.repo,
        from: prev.status,
        to: status,
        reasons,
      });
    }
  }

  // Prepare outputs
  const payload = {
    criteriaVersion: CRITERIA_VERSION,
    evaluatedAt: now.toISOString(),
    itemCount: evaluatedItems.length,
    summary: {
      eligible: evaluatedItems.filter((i) => i.status === 'eligible').length,
      pendingReview: evaluatedItems.filter((i) => i.status === 'pending-review').length,
      belowThreshold: evaluatedItems.filter((i) => i.status === 'below-threshold').length,
      unavailable: evaluatedItems.filter((i) => i.status === 'unavailable').length,
      stale: evaluatedItems.filter((i) => i.stale).length,
    },
    changes,
    items: evaluatedItems,
  };

  // 1. Write public/data/gems.json
  const currentPath = path.join(ROOT_DIR, 'public/data/gems.json');
  await fs.mkdir(path.dirname(currentPath), { recursive: true });
  await fs.writeFile(currentPath, JSON.stringify(payload, null, 2), 'utf-8');
  console.log(`[EVALUATOR] Successfully updated ${currentPath}`);

  // 2. Write immutable history snapshot public/data/gems-history/YYYY-MM.json
  const yearMonth = `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, '0')}`;
  const historyPath = path.join(ROOT_DIR, `public/data/gems-history/${yearMonth}.json`);
  await fs.mkdir(path.dirname(historyPath), { recursive: true });

  try {
    await fs.access(historyPath);
    console.log(`[EVALUATOR] Snapshot ${historyPath} already exists. Skipping overwrite.`);
  } catch {
    await fs.writeFile(historyPath, JSON.stringify(payload, null, 2), 'utf-8');
    console.log(`[EVALUATOR] Created immutable snapshot ${historyPath}`);
  }

  return payload;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  evaluateGems().catch((err) => {
    console.error('[FATAL] Evaluator failed:', err);
    process.exit(1);
  });
}
```

