```yaml
name: Monthly Gems Refresh & Evaluation

on:
  schedule:
    # Runs on the 1st of every month at 06:00 UTC
    - cron: '0 6 1 * *'
  workflow_dispatch:

permissions:
  contents: write
  pull-requests: write

jobs:
  evaluate-and-snapshot:
    runs-on: ubuntu-latest

    steps:
      - name: Checkout Repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Setup Node.js 20
        uses: actions/setup-node@v4
        with:
          node-version: 20
          cache: 'npm'

      - name: Install Dependencies
        run: npm ci

      - name: Run Monthly Gems Evaluator
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
        run: node scripts/evaluate-gems.mjs

      - name: Run Test Suite
        run: node --test tests/gems.test.mjs

      - name: Get Current Month Label
        id: date
        run: echo "month=$(date -u +'%Y-%m')" >> $GITHUB_OUTPUT

      - name: Create Pull Request on Changes (Branch Protection Safe)
        uses: peter-evans/create-pull-request@v6
        with:
          token: ${{ secrets.GITHUB_TOKEN }}
          commit-message: "chore(gems): monthly evaluation snapshot [${{ steps.date.outputs.month }}]"
          branch: "gems/monthly-${{ steps.date.outputs.month }}"
          delete-branch: true
          title: "Automated Monthly Gems Refresh (${{ steps.date.outputs.month }})"
          body: |
