### 6. The Updated Client Service (`src/services/gemsService.js`)

```javascript
/**
 * ExploreGit Gems Client Service
 * Consumes static precomputed /data/gems.json with zero runtime GitHub API rate-limit overhead.
 */

import { GEMS_CATEGORIES } from '../data/gemsManifest';

const GEMS_STATIC_URL = '/data/gems.json';

const formatStars = (num) => {
  if (!num) return '0';
  if (num >= 1_000_000) return `${(num / 1_000_000).toFixed(1)}M`;
  if (num >= 1_000) return `${(num / 1_000).toFixed(1)}k`;
  return `${num}`;
};

export const gemsService = {
  /**
   * Fetch static precomputed gems data.
   * By default filters to display only eligible, pending-review, and stale items.
   *
   * @param {Object} options
   * @param {boolean} options.includeBelowThreshold - Whether to include failing entries
   */
  async getGems({ includeBelowThreshold = false } = {}) {
    try {
      const res = await fetch(GEMS_STATIC_URL, {
        headers: { Accept: 'application/json' },
      });

      if (!res.ok) {
        throw new Error(`Failed to load gems dataset (HTTP ${res.status})`);
      }

      const payload = await res.json();
      const allItems = (payload.items || []).map((item, idx) => ({
        ...item,
        starsFormatted: formatStars(item.stars),
        forksFormatted: formatStars(item.forks),
        rank: idx + 1,
      }));

      // Filter visible items according to policy
      const visibleItems = includeBelowThreshold
        ? allItems
        : allItems.filter(
            (item) =>
              item.status === 'eligible' ||
              item.status === 'pending-review' ||
              item.stale === true
          );

      return {
        items: visibleItems,
        allItems,
        evaluatedAt: payload.evaluatedAt ? new Date(payload.evaluatedAt) : null,
        criteriaVersion: payload.criteriaVersion || 1,
        summary: payload.summary || {},
        staleNotice: 'Star counts and metrics are evaluated monthly and may be up to 30 days old.',
      };
    } catch (err) {
      console.error('[gemsService] Failed to load static gems:', err);
      return {
        items: [],
        allItems: [],
        evaluatedAt: null,
        criteriaVersion: null,
        summary: {},
        error: err.message,
      };
    }
  },

  /**
   * Derive category breakdown counts from currently active item set
   */
  getCategories(items = []) {
    return GEMS_CATEGORIES.map((cat) => {
      const count =
        cat.id === 'all'
          ? items.length
          : items.filter((item) => item.category === cat.id).length;
      return { ...cat, count };
    });
  },
};
