import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { CRITERIA, CRITERIA_VERSION } from '../data/criteria.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');

// Clearly labeled mock fixtures
const MOCK_FIXTURES = {
  validLegendRepo: {
    name: 'ripgrep',
    archived: false,
    disabled: false,
    fork: false,
    description: 'Fast line-oriented search tool',
    stargazers_count: 48000,
    created_at: '2016-09-01T00:00:00Z',
    pushed_at: new Date().toISOString(),
    license: { spdx_id: 'MIT' },
    topics: ['cli', 'search'],
  },
  validRelease: { tag_name: '14.1.0' },
  validCommunityProfile: {
    files: {
      readme: { url: 'https://...' },
      security_policy: { url: 'https://...' },
    },
  },
  validCommits: [
    { author: { login: 'dev1' } },
    { author: { login: 'dev2' } },
    { author: { login: 'dev3' } },
    { author: { login: 'dev4' } },
    { author: { login: 'dev5' } },
  ],
};

describe('Criteria Registry Invariants', () => {
  it('criteria IDs are append-only and preserve all historical IDs', async () => {
    const rawIds = await fs.readFile(path.join(ROOT, 'data/criteria-ids.json'), 'utf-8');
    const expectedIds = JSON.parse(rawIds);
    const registeredIds = new Set(CRITERIA.map((c) => c.id));

    for (const expectedId of expectedIds) {
      assert.ok(
        registeredIds.has(expectedId),
        `Historical criterion "${expectedId}" must never be deleted or renamed.`
      );
    }
  });

  it('every criterion has a valid "since" integer and "kind" of "auto" or "manual"', () => {
    for (const criterion of CRITERIA) {
      assert.ok(
        Number.isInteger(criterion.since) && criterion.since > 0 && criterion.since <= CRITERIA_VERSION,
        `Criterion ${criterion.id} has invalid "since" version`
      );
      assert.ok(
        criterion.kind === 'auto' || criterion.kind === 'manual',
        `Criterion ${criterion.id} kind must be "auto" or "manual"`
      );
      assert.equal(typeof criterion.applies, 'function');
      assert.equal(typeof criterion.check, 'function');
    }
  });

  it('manual criteria return pass: false when no review record exists', () => {
    const manualCriteria = CRITERIA.filter((c) => c.kind === 'manual');
    const entry = { repo: 'example/tool', category: 'security-privacy', isLegend: true };
    const emptyContext = { reviewRecord: null, now: new Date() };

    for (const criterion of manualCriteria) {
      if (criterion.applies(entry, emptyContext)) {
        const result = criterion.check(entry, emptyContext);
        assert.equal(
          result.pass,
          false,
          `Manual criterion "${criterion.id}" must never pass without a valid review record.`
        );
      }
    }
  });

  it('manual criteria return pass: false when review record is expired', () => {
    const issueCriterion = CRITERIA.find((c) => c.id === 'issue-responsiveness');
    const expiredContext = {
      reviewRecord: {
        issueResponsiveness: {
          verifiedAt: new Date(Date.now() - 120 * 24 * 60 * 60 * 1000).toISOString(), // 120 days old (limit 90)
          reviewer: 'test-auditor',
        },
      },
      now: new Date(),
    };

    const res = issueCriterion.check({ repo: 'example/tool' }, expiredContext);
    assert.equal(res.pass, false);
    assert.match(res.reason, /expired/i);
  });
});

describe('Evaluator Behavior & Resilience', () => {
  it('a failed fetch marks entry as stale: true rather than below-threshold', () => {
    const prevEntry = {
      repo: 'BurntSushi/ripgrep',
      status: 'eligible',
      stars: 48000,
    };

    // Simulate recovery logic from evaluator when fetch fails
    const fetchFailed = true;
    const item = fetchFailed
      ? { ...prevEntry, stale: true, staleReason: 'Network error 500' }
      : { ...prevEntry, status: 'below-threshold' };

    assert.equal(item.status, 'eligible');
    assert.equal(item.stale, true);
    assert.match(item.staleReason, /Network error/);
  });

  it('changes array correctly detects status transitions between runs', () => {
    const previousMap = new Map([
      ['example/tool-a', { status: 'eligible' }],
      ['example/tool-b', { status: 'pending-review' }],
    ]);

    const evaluated = [
      { repo: 'example/tool-a', status: 'below-threshold', reasons: ['Repository archived'] },
      { repo: 'example/tool-b', status: 'eligible', reasons: [] },
    ];

    const changes = [];
    for (const curr of evaluated) {
      const prev = previousMap.get(curr.repo);
      if (prev && prev.status !== curr.status) {
        changes.push({ repo: curr.repo, from: prev.status, to: curr.status });
      }
    }

    assert.equal(changes.length, 2);
    assert.deepEqual(changes[0], { repo: 'example/tool-a', from: 'eligible', to: 'below-threshold' });
    assert.deepEqual(changes[1], { repo: 'example/tool-b', from: 'pending-review', to: 'eligible' });
  });

  it('evaluator output is deterministic given identical mock inputs', () => {
    const entry = { repo: 'BurntSushi/ripgrep', isLegend: true, category: 'cli-devtools' };
    const fixedNow = new Date('2026-11-01T00:00:00Z');
    const context = {
      now: fixedNow,
      repo: MOCK_FIXTURES.validLegendRepo,
      latestRelease: MOCK_FIXTURES.validRelease,
      communityProfile: MOCK_FIXTURES.validCommunityProfile,
      commits: MOCK_FIXTURES.validCommits,
      reviewRecord: {
        issueResponsiveness: {
          verifiedAt: '2026-10-15T00:00:00Z',
          reviewer: 'editor',
        },
      },
    };

    const runEvaluation = () => {
      const failed = [];
      for (const criterion of CRITERIA) {
        if (!criterion.applies(entry, context)) continue;
        const res = criterion.check(entry, context);
        if (!res.pass) failed.push(criterion.id);
      }
      return failed;
    };

    const firstRun = runEvaluation();
    const secondRun = runEvaluation();
    assert.deepEqual(firstRun, secondRun);
    assert.equal(firstRun.length, 0); // Passes all criteria
  });
});
```

---

### 8. Migration Plan (Zero-Downtime Rollout)

1. **Step 1: Bootstrap the Static File Locally**
   Before deploying code changes, run `node scripts/evaluate-gems.mjs` locally with a valid `GITHUB_TOKEN` to generate `public/data/gems.json`. Commit this baseline data file to Git so that Vercel deploys with a pre-existing JSON endpoint immediately.
2. **Step 2: Update `gemsService.js` and Verify the Client**
   Replace the implementation of `src/services/gemsService.js`. In the browser, verify that `Gems.jsx` renders without making outgoing calls to `api.github.com`. The UI continues reading `result.items`, maintaining component compatibility.
3. **Step 3: Update `Gems.jsx` Header Presentation**
   Add a timestamp display reading `result.evaluatedAt` alongside the existing category pills, accompanied by a small tooltip: *"Evaluated monthly. Star metrics may be up to 30 days old."*
4. **Step 4: Enable the GitHub Actions Workflow**
   Merge `.github/workflows/gems-monthly.yml`. Trigger a manual run using GitHub's **Run workflow** button (`workflow_dispatch`) to verify the end-to-end execution, test runner pass, and PR creation.

---

### 9. Pre-Launch Decisions & Recommendations

| Decision Area | Trade-off / Choice | Recommendation |
| :--- | :--- | :--- |
| **Tier Migration Policy** | Auto-promotion vs. Human Approval | **Human Approval (Strict):** If an *Under the Radar* project crosses 1,000 stars, keep it flagged as `below-threshold` until an editor changes its manifest flag to `gem`. This prevents uncurated tools from auto-advancing into legacy tiers. |
| **Branch Protection Strategy** | Direct Commit vs. Automated PR | **Automated PR (`peter-evans/create-pull-request`):** Most production repositories enforce branch protection on `main`. An automated monthly PR creates an audit trail, lets maintainers review status drops, and prevents pipeline failures. |
| **Security Classification** | Dedicated Category vs. Topic Heuristics | **Topic Heuristics in v2:** Check both `category` and repository `topics` for security keywords. This allows tools in `cli-devtools` or `essential-legends` (like `gh-secure` and `bleachbit`) to be evaluated for security policies without redesigning the navigation tabs. |
| **Handling Stale Entries** | Hide Stale vs. Show Stale with Badge | **Show Stale with Badge:** If GitHub experiences a 500 or network timeout during the scheduled run, retain the tool's previous state and render a subtle *"stale"* indicator rather than removing a trusted tool from user view. |

