/**
 * Fetch data for an individual repository
 */
async function fetchRepoData(repoFullName, isSecuritySensitive, now) {
  const [owner, repo] = repoFullName.split('/');
  const base = `https://api.github.com/repos/${owner}/${repo}`;
  const oneYearAgoISO = new Date(now.getTime() - 365 * 24 * 60 * 60 * 1000).toISOString();

  // 1. Core repo metadata
  const repoRes = await fetchGithub(base);
  if (!repoRes.ok && repoRes.status === 404) {
    return { unavailable: true };
  }
  if (!repoRes.ok) {
    throw new Error(`Failed to fetch repo ${repoFullName} (HTTP ${repoRes.status})`);
  }

  // 2. Latest release
  const releaseRes = await fetchGithub(`${base}/releases/latest`).catch(() => ({ ok: false, data: null }));

  // 3. Community profile (README presence)
  const communityRes = await fetchGithub(`${base}/community/profile`).catch(() => ({ ok: false, data: null }));

  // 4. Commits in the last 365 days (max 100 sample)
  const commitsRes = await fetchGithub(`${base}/commits?since=${encodeURIComponent(oneYearAgoISO)}&per_page=100`).catch(() => ({ ok: false, data: [] }));

  // 5. Security policy (verified file presence if security-sensitive)
  let hasSecurityPolicy = false;
  if (isSecuritySensitive) {
    const secResRoot = await fetchGithub(`${base}/contents/SECURITY.md`).catch(() => ({ ok: false }));
    if (secResRoot.ok) {
      hasSecurityPolicy = true;
    } else {
      const secResDot = await fetchGithub(`${base}/contents/.github/SECURITY.md`).catch(() => ({ ok: false }));
      if (secResDot.ok) hasSecurityPolicy = true;
    }
  }

  return {
    unavailable: false,
    repo: repoRes.data,
    latestRelease: releaseRes?.data || null,
    communityProfile: communityRes?.data || null,
    hasReadme: Boolean(communityRes?.data?.files?.readme),
    commits: Array.isArray(commitsRes?.data) ? commitsRes.data : [],
    hasSecurityPolicy,
  };
}

/**
 * Strip reviewer names from review records for public consumption
 */
function sanitizeReviewForPublish(reviewRecord) {
  if (!reviewRecord) return null;
  const sanitized = {};
  if (reviewRecord.issueResponsiveness) {
    sanitized.issueResponsiveness = {
      verifiedAt: reviewRecord.issueResponsiveness.verifiedAt,
      notes: reviewRecord.issueResponsiveness.notes,
    };
  }
  if (reviewRecord.independentAudit) {
    sanitized.independentAudit = {
      verifiedAt: reviewRecord.independentAudit.verifiedAt,
      auditUrl: reviewRecord.independentAudit.auditUrl,
      auditor: reviewRecord.independentAudit.auditor,
      notes: reviewRecord.independentAudit.notes,
    };
  }
  return sanitized;
}

/**
 * Main Evaluation Engine
 */
export async function evaluateGems() {
  const now = new Date();
  console.log(`[EVALUATOR] Starting Gems evaluation at ${now.toISOString()} (Criteria v${CRITERIA_VERSION})...`);

  // Validate reviews upfront
  const reviews = await loadManualReviews();

  // Load previous state
  const previousState = await loadPreviousState();
  const isBaselineRun = !previousState;
  const previousItemsMap = new Map((previousState?.items || []).map((i) => [i.id || i.repo.toLowerCase(), i]));

  // Pre-flight rate limit check (est 4 calls per entry + 1 sec check)
  const estimatedApiCalls = GEMS_MANIFEST.length * 4;
  await checkPreFlightRateLimit(estimatedApiCalls);

  const evaluatedItems = [];
  const changes = [];
  let statusChangedCount = 0;
  let fetchFailureCount = 0;

  for (const manifestItem of GEMS_MANIFEST) {
    const itemKey = manifestItem.id || manifestItem.repo.toLowerCase();
    const prev = previousItemsMap.get(itemKey);
    console.log(`[EVALUATOR] Evaluating ${manifestItem.id} (${manifestItem.repo})...`);

    let repoData;
    let fetchError = null;

    try {
      repoData = await fetchRepoData(manifestItem.repo, manifestItem.isSecuritySensitive === true, now);
    } catch (err) {
      fetchError = err;
      fetchFailureCount++;
    }

    // Handle Network / API Fetch Failures
    if (fetchError) {
      if (prev) {
        console.warn(`[WARN] Fetch failed for ${manifestItem.repo}. Retaining previous state with stale: true`);
        evaluatedItems.push({
          ...prev,
          stale: true,
          staleReason: `GitHub fetch failed: ${fetchError.message}`,
        });
      } else {
        console.warn(`[WARN] Initial fetch failed for new entry ${manifestItem.repo}. Marking unknown.`);
        evaluatedItems.push({
          ...manifestItem,
          status: 'unknown',
          tier: 'under-the-radar',
          stale: true,
          staleReason: `Initial fetch failed: ${fetchError.message}`,
          failingCriteria: [],
          evaluatedAt: now.toISOString(),
        });
      }
      continue;
    }

    // Handle 404 Deleted or Renamed Repos
    if (repoData.unavailable) {
      const item = {
        ...manifestItem,
        status: 'unavailable',
        tier: prev?.tier || 'under-the-radar',
        stale: false,
        failingCriteria: [{ id: 'repository-exists', detail: 'Repository returned 404 Not Found' }],
        evaluatedAt: now.toISOString(),
      };
      evaluatedItems.push(item);

      if (prev && prev.status !== 'unavailable') {
        changes.push({
          type: 'status',
          id: manifestItem.id,
          repo: manifestItem.repo,
          from: prev.status,
          to: 'unavailable',
        });
        statusChangedCount++;
      }
      continue;
    }

    // 1. Derive Tier dynamically from current star count
    const stars = repoData.repo.stargazers_count ?? 0;
    const currentTier = deriveTier(stars);
    const prevTier = prev?.tier;

    if (prevTier && prevTier !== currentTier) {
      changes.push({
        type: 'tier',
        id: manifestItem.id,
        repo: manifestItem.repo,
        from: prevTier,
        to: currentTier,
      });
    }

    // 2. Ownership transfer detection
    const currentOwner = repoData.repo.owner?.login;
    const prevOwner = prev?.ownerLogin;
    if (prevOwner && currentOwner && prevOwner.toLowerCase() !== currentOwner.toLowerCase()) {
      changes.push({
        type: 'ownership-transfer',
        id: manifestItem.id,
        repo: manifestItem.repo,
        from: prevOwner,
        to: currentOwner,
      });
    }

    // 3. Evaluate criteria against derived tier
    const reviewRecord = reviews[manifestItem.id] || reviews[manifestItem.repo] || null;
    const context = {
      now,
      repo: repoData.repo,
      tier: currentTier,
      latestRelease: repoData.latestRelease,
      communityProfile: repoData.communityProfile,
      hasReadme: repoData.hasReadme,
      commits: repoData.commits,
      hasSecurityPolicy: repoData.hasSecurityPolicy,
      reviewRecord,
    };

    const failingCriteria = [];
    let hasFailedAuto = false;
    let hasFailedManual = false;

    for (const criterion of CRITERIA) {
      if (criterion.retired) continue;
      if (!criterion.applies(manifestItem, context)) continue;

      const result = criterion.check(manifestItem, context);
      if (!result.pass) {
        failingCriteria.push({
          id: criterion.id,
          kind: criterion.kind,
          detail: result.detail || 'Criterion check failed',
        });

        if (criterion.kind === 'auto') {
          hasFailedAuto = true;
        } else if (criterion.kind === 'manual') {
          hasFailedManual = true;
        }
      }
    }

    // Status assignment
    let status = 'eligible';
    if (hasFailedAuto) {
      status = 'below-threshold';
    } else if (hasFailedManual) {
      status = 'pending-review';
    }

    // Construct final entry
    const entry = {
      ...manifestItem,
      name: manifestItem.name || repoData.repo.name,
      description: repoData.repo.description || manifestItem.tagline,
      stars,
      forks: repoData.repo.forks_count ?? 0,
      language: repoData.repo.language || 'Multi',
      license: repoData.repo.license?.spdx_id || 'Open Source',
      topics: repoData.repo.topics || [],
      githubUrl: repoData.repo.html_url,
      avatarUrl: repoData.repo.owner?.avatar_url,
      ownerLogin: currentOwner,
      tier: currentTier,
      status,
      stale: false,
      failingCriteria,
      verifiedReview: sanitizeReviewForPublish(reviewRecord),
      evaluatedAt: now.toISOString(),
    };

    evaluatedItems.push(entry);

    if (prev && prev.status !== status) {
      changes.push({
        type: 'status',
        id: manifestItem.id,
        repo: manifestItem.repo,
        from: prev.status,
        to: status,
        reasons: failingCriteria.map((f) => f.detail),
      });
      statusChangedCount++;
    }
  }

  // 4. Run-Level Failure Check: abort if too many fetch failures occurred (> 50%)
  if (GEMS_MANIFEST.length > 0 && fetchFailureCount / GEMS_MANIFEST.length > 0.5) {
    const partialPath = path.join(ROOT_DIR, 'reports/gems-eval-partial.json');
    await fs.mkdir(path.dirname(partialPath), { recursive: true });
    await fs.writeFile(partialPath, JSON.stringify({ evaluatedItems, changes }, null, 2), 'utf-8');
    throw new Error(`[FATAL] More than 50% of fetches failed (${fetchFailureCount}/${GEMS_MANIFEST.length}). Run aborted without publishing.`);
  }

  // 5. Publish Guard (25% anomaly check)
  if (!isBaselineRun && previousState.items?.length > 0) {
    const totalPrevious = previousState.items.length;
    const changeRatio = statusChangedCount / totalPrevious;

    if (changeRatio > CONFIG.publishAnomalyThreshold) {
      const yearMonth = `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, '0')}`;
      const anomalyReportPath = path.join(ROOT_DIR, `reports/gems-anomaly-${yearMonth}.json`);
      const anomalyReport = {
        evaluatedAt: now.toISOString(),
        totalEntries: totalPrevious,
        statusChangedCount,
        changeRatio,
        threshold: CONFIG.publishAnomalyThreshold,
        changes,
      };

      await fs.mkdir(path.dirname(anomalyReportPath), { recursive: true });
      await fs.writeFile(anomalyReportPath, JSON.stringify(anomalyReport, null, 2), 'utf-8');

      console.error(`[ANOMALY GUARD] ${Math.round(changeRatio * 100)}% of entries changed status (limit: ${CONFIG.publishAnomalyThreshold * 100}%).`);
      console.error(`[ANOMALY GUARD] Anomaly report written to ${anomalyReportPath}. Exiting without publishing.`);
      process.exit(1);
    }
  }

  // 6. Summary and Observability
  const runSummary = {
    evaluatedAt: now.toISOString(),
    criteriaVersion: CRITERIA_VERSION,
    totalEntries: evaluatedItems.length,
    statusCounts: {
      eligible: evaluatedItems.filter((i) => i.status === 'eligible').length,
      pendingReview: evaluatedItems.filter((i) => i.status === 'pending-review').length,
      belowThreshold: evaluatedItems.filter((i) => i.status === 'below-threshold').length,
      unavailable: evaluatedItems.filter((i) => i.status === 'unavailable').length,
      unknown: evaluatedItems.filter((i) => i.status === 'unknown').length,
    },
    staleCount: evaluatedItems.filter((i) => i.stale).length,
    apiCallsMade: totalApiCallsMade,
    rateLimitRemaining: lastKnownRateLimitRemaining,
    anomalyGuard: isBaselineRun
      ? { skipped: true, reason: 'Baseline run: no prior state exists to compare' }
      : { passed: true, statusChangedCount, threshold: CONFIG.publishAnomalyThreshold },
  };

  const snapshotPayload = {
    criteriaVersion: CRITERIA_VERSION,
    evaluatedAt: now.toISOString(),
    runSummary,
    changes,
    items: evaluatedItems,
  };

  // 7. Write Immutable Monthly Snapshot (public/data/gems-history/YYYY-MM.json)
  const yearMonth = `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, '0')}`;
  const historyPath = path.join(ROOT_DIR, `public/data/gems-history/${yearMonth}.json`);
  await fs.mkdir(path.dirname(historyPath), { recursive: true });

  try {
    await fs.access(historyPath);
    throw new Error(`[IMMUTABLE SNAPSHOT VIOLATION]: History file ${historyPath} already exists! Monthly snapshots cannot be overwritten.`);
  } catch (err) {
    if (err.code === 'ENOENT') {
      await fs.writeFile(historyPath, JSON.stringify(snapshotPayload, null, 2), 'utf-8');
      console.log(`[OUTPUT] Wrote immutable snapshot to ${historyPath}`);
    } else {
      throw err;
    }
  }

  // 8. Write Current Active State (public/data/gems.json)
  const currentPath = path.join(ROOT_DIR, 'public/data/gems.json');
  await fs.mkdir(path.dirname(currentPath), { recursive: true });
  await fs.writeFile(currentPath, JSON.stringify(snapshotPayload, null, 2), 'utf-8');
  console.log(`[OUTPUT] Updated active dataset at ${currentPath}`);

  // Observability Log Output
  console.log('\n═══════════════════════════════════════════════════════════════');
  console.log('                 EXPLOREGIT GEMS RUN SUMMARY                   ');
  console.log('═══════════════════════════════════════════════════════════════');
  console.log(`Criteria Version:     v${CRITERIA_VERSION}`);
  console.log(`Total Repositories:   ${runSummary.totalEntries}`);
  console.log(`  - Eligible:         ${runSummary.statusCounts.eligible}`);
  console.log(`  - Pending Review:   ${runSummary.statusCounts.pendingReview}`);
  console.log(`  - Below Threshold:  ${runSummary.statusCounts.belowThreshold}`);
  console.log(`  - Unavailable:      ${runSummary.statusCounts.unavailable}`);
  console.log(`  - Unknown:          ${runSummary.statusCounts.unknown}`);
  console.log(`Stale Entries:        ${runSummary.staleCount}`);
  console.log(`Total API Calls Made: ${runSummary.apiCallsMade}`);
  console.log(`Rate Limit Remaining: ${runSummary.rateLimitRemaining ?? 'N/A'}`);
  console.log(`Changes Recorded:     ${changes.length}`);
  console.log('═══════════════════════════════════════════════════════════════\n');

  return snapshotPayload;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  evaluateGems().catch((err) => {
    console.error('[FATAL EVALUATION FAILURE]:', err.message);
    process.exit(1);
  });
}

/**
 * ExploreGit Gems Client Service
 *
 * Consumes precomputed static dataset at `/data/gems.json`.
 * All client-side GitHub API rate-limiting and authorization headers have been removed.
 */

import { GEMS_MANIFEST, GEMS_CATEGORIES } from '../data/gemsManifest';

const GEMS_STATIC_URL = '/data/gems.json';

// Language color mappings for UI badges
const LANG_COLORS = {
  JavaScript: '#F7DF1E',
  TypeScript: '#3178c6',
  Python: '#3572A5',
  Rust: '#DEA584',
  Go: '#00ADD8',
  C: '#555555',
  'C++': '#F34B7D',
  'C#': '#178600',
  Kotlin: '#A97BFF',
  Dart: '#00B4AB',
  Shell: '#89e051',
  Swift: '#F05138',
};

const formatStars = (num) => {
  if (!num) return '0';
  if (num >= 1_000_000) return `${(num / 1_000_000).toFixed(1)}M`;
  if (num >= 1_000) return `${(num / 1_000).toFixed(1)}k`;
  return `${num}`;
};

/**
 * Format status for human readability and accessible assistive technology
 */
export const STATUS_LABELS = {
  eligible: {
    label: 'Eligible Gem',
    badge: 'Eligible',
    description: 'Passed all active automated and editorial criteria.',
    colorClass: 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20',
  },
  'pending-review': {
    label: 'Pending Review',
    badge: 'Under Review',
    description: 'Passed automated metrics; awaiting annual or quarterly editorial verification.',
    colorClass: 'text-amber-400 bg-amber-500/10 border-amber-500/20',
  },
  'below-threshold': {
    label: 'Below Threshold',
    badge: 'Below Threshold',
    description: 'Currently does not meet one or more activity, licensing, or freshness criteria.',
    colorClass: 'text-rose-400 bg-rose-500/10 border-rose-500/20',
  },
  unavailable: {
    label: 'Unavailable',
    badge: '404 Missing',
    description: 'Repository was deleted, privatized, or moved without a redirect.',
    colorClass: 'text-zinc-400 bg-zinc-500/10 border-zinc-500/20',
  },
  unknown: {
    label: 'Fetch Incomplete',
    badge: 'Unknown',
    description: 'Could not obtain upstream GitHub metrics during the latest evaluation run.',
    colorClass: 'text-zinc-400 bg-zinc-500/10 border-zinc-500/20',
  },
};

export const gemsService = {
  /**
   * Fetch precomputed monthly gems dataset.
   *
   * By default, returns only eligible, pending-review, and stale entries.
   * Pass includeBelowThreshold: true to display failing entries with transparency reasons.
   */
  async getGems(options = {}) {
    const includeBelowThreshold = typeof options === 'boolean' ? options : Boolean(options.includeBelowThreshold);

    try {
      const res = await fetch(GEMS_STATIC_URL, {
        headers: { Accept: 'application/json' },
      });

      if (!res.ok) {
        throw new Error(`HTTP ${res.status}: ${res.statusText}`);
      }

      const payload = await res.json();
      const rawItems = Array.isArray(payload.items) ? payload.items : [];

      const hydratedItems = rawItems.map((item, idx) => ({
        ...item,
        rank: idx + 1,
        starsFormatted: formatStars(item.stars),
        forksFormatted: formatStars(item.forks),
        languageColor: LANG_COLORS[item.language] || '#71717A',
        statusMeta: STATUS_LABELS[item.status] || STATUS_LABELS.unknown,
      }));

      // Filter default visibility: eligible, pending-review, and stale
      const visibleItems = includeBelowThreshold
        ? hydratedItems
        : hydratedItems.filter(
            (item) =>
              item.status === 'eligible' ||
              item.status === 'pending-review' ||
              item.stale === true
          );

      const evaluatedDate = payload.evaluatedAt ? new Date(payload.evaluatedAt) : new Date();

      return {
        items: visibleItems,
        allItems: hydratedItems,
        isCached: true,
        lastUpdated: evaluatedDate,
        evaluatedAt: evaluatedDate,
        criteriaVersion: payload.criteriaVersion || 1,
        runSummary: payload.runSummary || {},
        staleNotice: 'Metrics and star counts are evaluated monthly and may be up to 30 days old.',
      };
    } catch (err) {
      console.warn('[gemsService] Failed to load static dataset, falling back to local manifest:', err.message);

      // Fallback baseline for local development before first evaluation run
      const fallbackItems = GEMS_MANIFEST.map((item, idx) => ({
        ...item,
        rank: idx + 1,
        description: item.tagline,
        stars: item.isLegend ? 15000 : 2500,
        starsFormatted: item.isLegend ? '15k' : '2.5k',
        forks: 150,
        forksFormatted: '150',
        language: 'Code',
        languageColor: '#71717A',
        topics: ['open-source', 'curated'],
        license: 'Open Source',
        githubUrl: `https://github.com/${item.repo}`,
        status: 'eligible',
        statusMeta: STATUS_LABELS.eligible,
        stale: true,
        staleReason: 'Static dataset not yet generated. Showing baseline manifest.',
        failingCriteria: [],
        evaluatedAt: null,
      }));

      return {
        items: fallbackItems,
        allItems: fallbackItems,
        isCached: false,
        lastUpdated: new Date(),
        evaluatedAt: null,
        criteriaVersion: 1,
        runSummary: {},
        staleNotice: 'Static dataset not yet generated. Showing baseline manifest.',
        error: err.message,
      };
    }
  },

  /**
   * Derive dynamic categories with accurate item counts
   */
  getCategories(items = []) {
    return GEMS_CATEGORIES.map((cat) => {
      const count =
        cat.id === 'all'
          ? items.length
          : items.filter((item) => item.category === cat.id).length;
      return { ...cat, count };
    });
  },

  /**
   * No-op cache reset retained for interface compatibility
   */
  clearCache() {
    // Static files are cached by browser HTTP semantics; no client storage key is used.
  },
};

/**
 * ExploreGit Gems Client Service
 *
 * Consumes precomputed static dataset at `/data/gems.json`.
 * All client-side GitHub API rate-limiting and authorization headers have been removed.
 */

import { GEMS_MANIFEST, GEMS_CATEGORIES } from '../data/gemsManifest';

const GEMS_STATIC_URL = '/data/gems.json';

// Language color mappings for UI badges
const LANG_COLORS = {
  JavaScript: '#F7DF1E',
  TypeScript: '#3178c6',
  Python: '#3572A5',
  Rust: '#DEA584',
  Go: '#00ADD8',
  C: '#555555',
  'C++': '#F34B7D',
  'C#': '#178600',
  Kotlin: '#A97BFF',
  Dart: '#00B4AB',
  Shell: '#89e051',
  Swift: '#F05138',
};

const formatStars = (num) => {
  if (!num) return '0';
  if (num >= 1_000_000) return `${(num / 1_000_000).toFixed(1)}M`;
  if (num >= 1_000) return `${(num / 1_000).toFixed(1)}k`;
  return `${num}`;
};

/**
 * Format status for human readability and accessible assistive technology
 */
export const STATUS_LABELS = {
  eligible: {
    label: 'Eligible Gem',
    badge: 'Eligible',
    description: 'Passed all active automated and editorial criteria.',
    colorClass: 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20',
  },
  'pending-review': {
    label: 'Pending Review',
    badge: 'Under Review',
    description: 'Passed automated metrics; awaiting annual or quarterly editorial verification.',
    colorClass: 'text-amber-400 bg-amber-500/10 border-amber-500/20',
  },
  'below-threshold': {
    label: 'Below Threshold',
    badge: 'Below Threshold',
    description: 'Currently does not meet one or more activity, licensing, or freshness criteria.',
    colorClass: 'text-rose-400 bg-rose-500/10 border-rose-500/20',
  },
  unavailable: {
    label: 'Unavailable',
    badge: '404 Missing',
    description: 'Repository was deleted, privatized, or moved without a redirect.',
    colorClass: 'text-zinc-400 bg-zinc-500/10 border-zinc-500/20',
  },
  unknown: {
    label: 'Fetch Incomplete',
    badge: 'Unknown',
    description: 'Could not obtain upstream GitHub metrics during the latest evaluation run.',
    colorClass: 'text-zinc-400 bg-zinc-500/10 border-zinc-500/20',
  },
};

export const gemsService = {
  /**
   * Fetch precomputed monthly gems dataset.
   *
   * By default, returns only eligible, pending-review, and stale entries.
   * Pass includeBelowThreshold: true to display failing entries with transparency reasons.
   */
  async getGems(options = {}) {
    const includeBelowThreshold = typeof options === 'boolean' ? options : Boolean(options.includeBelowThreshold);

    try {
      const res = await fetch(GEMS_STATIC_URL, {
        headers: { Accept: 'application/json' },
      });

      if (!res.ok) {
        throw new Error(`HTTP ${res.status}: ${res.statusText}`);
      }

      const payload = await res.json();
      const rawItems = Array.isArray(payload.items) ? payload.items : [];

      const hydratedItems = rawItems.map((item, idx) => ({
        ...item,
        rank: idx + 1,
        starsFormatted: formatStars(item.stars),
        forksFormatted: formatStars(item.forks),
        languageColor: LANG_COLORS[item.language] || '#71717A',
        statusMeta: STATUS_LABELS[item.status] || STATUS_LABELS.unknown,
      }));

      // Filter default visibility: eligible, pending-review, and stale
      const visibleItems = includeBelowThreshold
        ? hydratedItems
        : hydratedItems.filter(
            (item) =>
              item.status === 'eligible' ||
              item.status === 'pending-review' ||
              item.stale === true
          );

      const evaluatedDate = payload.evaluatedAt ? new Date(payload.evaluatedAt) : new Date();

      return {
        items: visibleItems,
        allItems: hydratedItems,
        isCached: true,
        lastUpdated: evaluatedDate,
        evaluatedAt: evaluatedDate,
        criteriaVersion: payload.criteriaVersion || 1,
        runSummary: payload.runSummary || {},
        staleNotice: 'Metrics and star counts are evaluated monthly and may be up to 30 days old.',
      };
    } catch (err) {
      console.warn('[gemsService] Failed to load static dataset, falling back to local manifest:', err.message);

      // Fallback baseline for local development before first evaluation run
      const fallbackItems = GEMS_MANIFEST.map((item, idx) => ({
        ...item,
        rank: idx + 1,
        description: item.tagline,
        stars: item.isLegend ? 15000 : 2500,
        starsFormatted: item.isLegend ? '15k' : '2.5k',
        forks: 150,
        forksFormatted: '150',
        language: 'Code',
        languageColor: '#71717A',
        topics: ['open-source', 'curated'],
        license: 'Open Source',
        githubUrl: `https://github.com/${item.repo}`,
        status: 'eligible',
        statusMeta: STATUS_LABELS.eligible,
        stale: true,
        staleReason: 'Static dataset not yet generated. Showing baseline manifest.',
        failingCriteria: [],
        evaluatedAt: null,
      }));

      return {
        items: fallbackItems,
        allItems: fallbackItems,
        isCached: false,
        lastUpdated: new Date(),
        evaluatedAt: null,
        criteriaVersion: 1,
        runSummary: {},
        staleNotice: 'Static dataset not yet generated. Showing baseline manifest.',
        error: err.message,
      };
    }
  },

  /**
   * Derive dynamic categories with accurate item counts
   */
  getCategories(items = []) {
    return GEMS_CATEGORIES.map((cat) => {
      const count =
        cat.id === 'all'
          ? items.length
          : items.filter((item) => item.category === cat.id).length;
      return { ...cat, count };
    });
  },

  /**
   * No-op cache reset retained for interface compatibility
   */
  clearCache() {
    // Static files are cached by browser HTTP semantics; no client storage key is used.
  },
};

/**
 * ExploreGit Gems Test Suite
 * Executed via Node's native test runner (node:test)
 */

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { CRITERIA, CRITERIA_VERSION, CONFIG, deriveTier } from '../data/criteria.mjs';
import { validateReviews } from '../scripts/evaluate-gems.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT_DIR = path.resolve(__dirname, '..');

// ── Clearly Labelled Mock Fixtures ──────────────────────────────────────────
const MOCK_FIXTURES = {
  // Standard Legend Repository
  legendRepo: {
    id: 1001,
    name: 'ripgrep',
    full_name: 'BurntSushi/ripgrep',
    owner: { login: 'BurntSushi' },
    archived: false,
    disabled: false,
    fork: false,
    description: 'Fast line-oriented search tool respecting gitignore',
    stargazers_count: 48500,
    forks_count: 2100,
    created_at: '2016-09-01T00:00:00Z',
    pushed_at: new Date().toISOString(),
    license: { spdx_id: 'MIT' },
    topics: ['cli', 'search', 'rust'],
  },
  // Under the Radar Repository (500 stars)
  underTheRadarRepo: {
    id: 1002,
    name: 'fieldwatch',
    full_name: 'OffGridPete/Fieldwatch',
    owner: { login: 'OffGridPete' },
    archived: false,
    disabled: false,
    fork: false,
    description: 'Passive radio observer for Android',
    stargazers_count: 520,
    forks_count: 45,
    created_at: '2023-01-01T00:00:00Z',
    pushed_at: new Date().toISOString(),
    license: { spdx_id: 'GPL-3.0' },
    topics: ['android', 'wifi'],
  },
  release: { tag_name: '14.1.0' },
  communityProfile: {
    files: {
      readme: { url: 'https://api.github.com/repos/.../readme' },
    },
  },
  commits: [
    { author: { login: 'alice' } },
    { author: { login: 'bob' } },
    { author: { login: 'carol' } },
    { author: { login: 'dave' } },
    { author: { login: 'eve' } },
  ],
};

describe('Criteria Registry Invariants', () => {
  it('criteria IDs are append-only and preserve all historical IDs from data/criteria-ids.json', async () => {
    const rawIds = await fs.readFile(path.join(ROOT_DIR, 'data/criteria-ids.json'), 'utf-8');
    const expectedIds = JSON.parse(rawIds);
    const registeredIds = new Set(CRITERIA.map((c) => c.id));

    for (const expectedId of expectedIds) {
      assert.ok(
        registeredIds.has(expectedId),
        `Historical criterion "${expectedId}" missing from registry! Deleting or renaming is prohibited.`
      );
    }
  });

  it('every criterion has a valid "since" integer, "retired" boolean, and valid "kind"', () => {
    for (const c of CRITERIA) {
      assert.ok(
        Number.isInteger(c.since) && c.since > 0 && c.since <= CRITERIA_VERSION,
        `Criterion ${c.id} has invalid "since" version (${c.since})`
      );
      assert.ok(
        c.kind === 'auto' || c.kind === 'manual',
        `Criterion ${c.id} kind must be "auto" or "manual"`
      );
      assert.equal(typeof c.retired, 'boolean', `Criterion ${c.id} must declare boolean retired state`);
      assert.equal(typeof c.applies, 'function', `Criterion ${c.id} must provide applies()`);
      assert.equal(typeof c.check, 'function', `Criterion ${c.id} must provide check()`);
    }
  });

  it('manual criteria return pass: false when no review record exists', () => {
    const manualCriteria = CRITERIA.filter((c) => c.kind === 'manual');
    const entry = { id: 'test-tool', isSecuritySensitive: true };
    const emptyContext = { reviewRecord: null, now: new Date() };

    for (const c of manualCriteria) {
      if (c.applies(entry, emptyContext)) {
        const result = c.check(entry, emptyContext);
        assert.equal(
          result.pass,
          false,
          `Manual criterion "${c.id}" must never pass without an editor review record.`
        );
      }
    }
  });

  it('manual criteria return pass: false when review record is expired', () => {
    const responsiveness = CRITERIA.find((c) => c.id === 'issue-responsiveness');
    const expiredContext = {
      now: new Date('2026-11-01T00:00:00Z'),
      reviewRecord: {
        issueResponsiveness: {
          verifiedAt: '2026-06-01T00:00:00Z', // > 90 days
          reviewer: 'editor-alice',
        },
      },
    };

    const res = responsiveness.check({}, expiredContext);
    assert.equal(res.pass, false);
    assert.match(res.detail, /expired/i);
  });
});

describe('Tier Boundaries & Dynamics', () => {
  it('correctly derives tiers strictly from star counts', () => {
    assert.equal(deriveTier(10000), 'legend');
    assert.equal(deriveTier(50000), 'legend');
    assert.equal(deriveTier(9999), 'gem');
    assert.equal(deriveTier(1000), 'gem');
    assert.equal(deriveTier(999), 'under-the-radar');
    assert.equal(deriveTier(150), 'under-the-radar');
    assert.equal(deriveTier(100), 'under-the-radar');
  });

  it('tier change alone does not change status; status is calculated separately', () => {
    const prevEntry = {
      id: 'tool-x',
      tier: 'under-the-radar',
      status: 'eligible',
    };

    // Stars grew from 800 to 1,500 (transitions from under-the-radar -> gem)
    const newStars = 1500;
    const newTier = deriveTier(newStars);
    const changes = [];

    if (prevEntry.tier !== newTier) {
      changes.push({
        type: 'tier',
        id: prevEntry.id,
        from: prevEntry.tier,
        to: newTier,
      });
    }

    assert.equal(changes.length, 1);
    assert.equal(changes[0].type, 'tier');
    assert.equal(changes[0].to, 'gem');

    // If new tier criteria pass, status remains eligible (no status change recorded)
    const newStatus = 'eligible';
    if (prevEntry.status !== newStatus) {
      changes.push({ type: 'status', id: prevEntry.id, from: prevEntry.status, to: newStatus });
    }

    assert.equal(changes.length, 1, 'No status change should be created if status remains eligible');
  });
});

describe('Evaluator Resilience & Failure Modes', () => {
  it('entries are never dropped on fetch error; preserved with stale: true and never marked below-threshold', () => {
    const prevSnapshot = [
      { id: 'vlc', repo: 'videolan/vlc', status: 'eligible', stars: 25000, tier: 'legend' },
    ];

    // Simulate fetch failure for vlc
    const fetchFailed = true;
    const evaluatedItems = [];

    if (fetchFailed) {
      const prev = prevSnapshot.find((i) => i.id === 'vlc');
      evaluatedItems.push({
        ...prev,
        stale: true,
        staleReason: 'GitHub API 503 Service Unavailable',
      });
    }

    assert.equal(evaluatedItems.length, 1);
    assert.equal(evaluatedItems[0].id, 'vlc');
    assert.equal(evaluatedItems[0].status, 'eligible', 'Must retain previous status');
    assert.equal(evaluatedItems[0].stale, true);
    assert.notEqual(evaluatedItems[0].status, 'below-threshold', 'Fetch error must never produce below-threshold');
  });

  it('ownership transfer is recorded when repository owner changes', () => {
    const prevItem = { id: 'cool-tool', repo: 'alice/cool-tool', ownerLogin: 'alice' };
    const currentRepo = { owner: { login: 'bob' }, stargazers_count: 2000 };
    const changes = [];

    if (prevItem.ownerLogin !== currentRepo.owner.login) {
      changes.push({
        type: 'ownership-transfer',
        id: prevItem.id,
        from: prevItem.ownerLogin,
        to: currentRepo.owner.login,
      });
    }

    assert.equal(changes.length, 1);
    assert.equal(changes[0].type, 'ownership-transfer');
    assert.equal(changes[0].from, 'alice');
    assert.equal(changes[0].to, 'bob');
  });

  it('publish guard blocks publication when status changes exceed 25%', () => {
    const totalEntries = 10;
    // 3 entries change status (30% change, exceeds 25% threshold)
    const statusChangedCount = 3;
    const ratio = statusChangedCount / totalEntries;

    assert.ok(
      ratio > CONFIG.publishAnomalyThreshold,
      `Ratio ${ratio} should exceed threshold ${CONFIG.publishAnomalyThreshold}`
    );
  });
});

describe('Manual Review Schema Validation', () => {
  it('validates a well-formed gem-reviews.json without error', () => {
    const validJson = JSON.stringify({
      version: 1,
      reviews: {
        ripgrep: {
          issueResponsiveness: {
            verifiedAt: '2026-11-01T00:00:00Z',
            reviewer: 'editor-alice',
            notes: 'Active maintainer triage',
          },
        },
      },
    });

    const reviews = validateReviews(validJson, 'test-reviews.json');
    assert.ok(reviews.ripgrep);
    assert.equal(reviews.ripgrep.issueResponsiveness.reviewer, 'editor-alice');
  });

  it('fails with clear error message when gem-reviews.json is malformed or invalid', () => {
    const malformedJson = JSON.stringify({
      version: 1,
      reviews: {
        ripgrep: {
          independentAudit: {
            verifiedAt: 'not-a-date',
            reviewer: 'editor-alice',
            auditUrl: 'invalid-url',
          },
        },
      },
    });

    assert.throws(
      () => validateReviews(malformedJson, 'data/gem-reviews.json'),
      (err) => {
        return err.message.includes('[SCHEMA ERROR in data/gem-reviews.json]') && err.message.includes('verifiedAt');
      }
    );
  });
});

describe('Deterministic Evaluation Output', () => {
  it('evaluator produces identical output given identical mock inputs', () => {
    const entry = { id: 'ripgrep', repo: 'BurntSushi/ripgrep', isSecuritySensitive: false };
    const fixedNow = new Date('2026-11-01T00:00:00Z');
    const tier = deriveTier(MOCK_FIXTURES.legendRepo.stargazers_count);

    const context = {
      now: fixedNow,
      repo: MOCK_FIXTURES.legendRepo,
      tier,
      latestRelease: MOCK_FIXTURES.release,
      communityProfile: MOCK_FIXTURES.communityProfile,
      hasReadme: true,
      commits: MOCK_FIXTURES.commits,
      hasSecurityPolicy: false,
      reviewRecord: {
        issueResponsiveness: {
          verifiedAt: '2026-10-15T00:00:00Z',
          reviewer: 'editor-sahid',
        },
      },
    };

    const runChecks = () => {
      const failing = [];
      for (const criterion of CRITERIA) {
        if (!criterion.applies(entry, context)) continue;
        const res = criterion.check(entry, context);
        if (!res.pass) failing.push({ id: criterion.id, detail: res.detail });
      }
      return failing;
    };

    const firstRun = runChecks();
    const secondRun = runChecks();

    assert.deepEqual(firstRun, secondRun);
    assert.equal(firstRun.length, 0, 'Legend mock repo with active review should pass all criteria');
  });
});

